const numberFrom = (value, fallback = 0) => {
  const parsed = Number(String(value ?? "").replace(/[^\d.-]/g, ""));
  return Number.isFinite(parsed) ? parsed : fallback;
};

const clampValue = (value, min, max) =>
  Math.min(Math.max(value, min), max);

